// A guided digital journey with a separate, voluntary record of workplace practice.
const FLOW = {
 start:T('Erste Einheit starten','Start the first lesson','Commencer la première séquence'),
 resume:T('Hier machst du weiter','Pick up where you left off','Reprendre votre parcours'),
 digital:T('Digital abgeschlossen','Digital lesson complete','Partie numérique terminée'),
 pending:T('Praxis noch offen','Practice still to do','Pratique à réaliser'),
 practised:T('Praxis selbst bestätigt','Practice self-confirmed','Pratique confirmée par vous'),
 next:T('Digital abschließen und weiter','Finish digital lesson and continue','Terminer la partie numérique et continuer'),
 overview:T('Dein Lernweg','Your learning journey','Votre parcours'),
 practice:T('Eine Aufgabe für deinen nächsten Dienst','One task for your next shift','Un exercice pour votre prochain service'),
 practiceHint:T('Du kannst direkt weiterlernen und diese Aufgabe später erledigen. Deine Bestätigung dokumentiert deine eigene Übung; sie ist keine Freigabe für selbstständiges Arbeiten.','You can keep learning now and do this task later. Your confirmation records your own practice; it is not authorisation to work independently.','Vous pouvez poursuivre le parcours et réaliser cet exercice plus tard. Votre confirmation atteste votre propre pratique ; elle ne vaut pas autorisation de travailler seul.'),
 finishFirst:T('Beantworte die Frage, bevor du den digitalen Teil abschließt. Die Praxis kannst du später erledigen.','Answer the question before completing the digital lesson. You can do the practice later.','Répondez à la question avant de terminer la partie numérique. La pratique peut attendre.'),
 ready:T('Der digitale Teil ist bereit zum Abschluss. Deine Praxis bleibt separat gespeichert.','You can now complete the digital lesson. Your practice is recorded separately.','Vous pouvez terminer la partie numérique. Votre pratique est enregistrée séparément.')
};
const PRACTICE = {
 welcome:T('Bereite einen kurzen Begrüßungssatz vor, der zu eurem Haus passt, und probiere ihn beim nächsten passenden Empfang aus.','Prepare a short welcome that suits your restaurant and try it at the next suitable opportunity.','Préparez une courte phrase d’accueil adaptée à la maison et essayez-la à la prochaine occasion.'),
 briefing:T('Halte nach dem nächsten Briefing eine Änderung fest, die deine Beratung am Tisch beeinflusst. Kläre offene Fragen vor einer Zusage an den Gast.','After the next briefing, note one change affecting your advice at the table. Resolve any uncertainty before making a promise to a guest.','Après le prochain briefing, retenez un changement utile pour conseiller les clients. Si un point reste flou, vérifiez-le avant de répondre à table.'),
 mise:REALISTIC_TASKS.mise[0],
 safety:T('Finde die aktuellen Allergeninformationen und kläre, wer eine unklare Anfrage verbindlich mit der Küche prüft.','Locate current allergen information and establish who checks uncertain requests with the kitchen.','Repérez les informations à jour sur les allergènes et demandez qui consulter en cas de doute.'),
 senses:T('Beschreibe bei einem vertrauten Lebensmittel, das du ohnehin zu dir nimmst, je einen Eindruck zu Duft, Geschmack und Mundgefühl.','With a familiar food you would normally eat, describe one impression each of aroma, taste and mouthfeel.','Choisissez un aliment que vous avez l’habitude de manger. Décrivez son arôme, sa saveur et sa texture.'),
 describe:T('Beschreibe ein bekanntes Gericht in einem Satz mit konkreten Aromen. Sprich ihn aus und streiche Wörter, die du am Tisch nicht verwenden würdest.','Describe a familiar dish in one sentence using specific aromas. Say it aloud and remove words you would not use at the table.','Décrivez un plat familier en une phrase avec des arômes précis. Dites-la à voix haute et retirez les mots que vous n’utiliseriez pas à table.'),
 cooking:T('Bestimme bei einem Gericht eurer Karte Hauptprodukt, Zubereitung und Sauce. Prüfe fehlende Angaben, bevor du das Gericht erklärst.','Identify the main ingredient, cooking method and sauce of one dish on your menu. Check missing details before explaining it.','Repérez le produit principal, la cuisson et la sauce d’un plat de votre carte. Vérifiez les informations manquantes avant de le présenter.'),
 produce:T('Prüfe für ein aktuelles Gericht eine Herkunftsangabe anhand der im Haus verfügbaren Informationen.','Verify one origin detail for a current dish using information available in your restaurant.','Choisissez un plat de la carte et vérifiez l’origine d’un de ses produits à l’aide des informations de la maison.'),
 wine:T('Vergleiche zwei offene Weine anhand eurer Unterlagen und formuliere einen belegbaren Unterschied, den ein Gast versteht. Du musst dafür nicht verkosten.','Compare two wines served by the glass using your restaurant’s information and explain one supported difference clearly. No tasting is required.','Consultez les informations sur deux vins au verre. Expliquez simplement une différence entre eux, sans inventer ce que vous ne savez pas. Vous n’avez pas besoin de les goûter pour cet exercice.'),
 pairing:T('Wähle ein aktuelles Gericht und ein verfügbares Getränk. Begründe die Kombination mit Sauce und Intensität und gleiche deinen Vorschlag bei Gelegenheit mit dem zuständigen Kollegen ab.','Choose a current dish and an available drink. Explain the pairing through sauce and intensity and discuss it with the responsible colleague when convenient.','Choisissez un plat et une boisson de la carte. Expliquez votre choix en tenant compte de la sauce et de l’intensité du plat, puis discutez-en avec un collègue à un moment calme.'),
 zero:T('Prüfe Zutaten und Alkoholangabe eines Getränks eurer alkoholfreien Auswahl. Bereite daraus eine verlässliche Empfehlung vor.','Check ingredients and alcohol information for one drink from your alcohol-free selection. Use this to prepare a reliable recommendation.','Vérifiez les ingrédients et la teneur en alcool d’une boisson de votre sélection sans alcool. Préparez un conseil fondé sur ces informations.'),
 bottle:T('Übe die Präsentation einer geschlossenen Flasche mit Wein, Produzent und Jahrgang. Öffne dafür keine Flasche; Öffnen und Einschenken übst du später unter Anleitung.','Practise presenting a sealed bottle, naming the wine, producer and vintage. Do not open it for this task; practise opening and pouring later under supervision.','Exercez-vous à présenter une bouteille fermée en annonçant le vin, le producteur et le millésime. Ne l’ouvrez pas pour cet exercice ; l’ouverture et le service se pratiquent ensuite sous supervision.'),
 consult:T('Wähle zwei verfügbare Getränke in ähnlichem Preisrahmen. Formuliere eine Frage, mit der du herausfindest, welches dem Gast eher gefällt.','Choose two available drinks in a similar price range. Formulate one question to discover which the guest would prefer.','Choisissez deux boissons disponibles dans un budget comparable. Formulez une question pour découvrir laquelle plairait davantage au convive.'),
 sequence:T('Schreibe eine fiktive Bestellung mit Tisch, Platz, Gericht und Sonderwunsch auf Papier. Prüfe die Zuordnung anhand eures Hausstandards.','Write a fictional order on paper with table, seat, dish and request. Check the details against your house procedure.','Écrivez une commande fictive sur papier en indiquant la table, la place, le plat et toute demande particulière. Vérifiez qu’un collègue pourrait la comprendre sans hésiter.'),
 explain:T('Stelle ein aktuelles Gericht mit Hauptprodukt, Zubereitung und einem Begleiter laut vor. Verwende geprüfte Angaben und halte die Erklärung bei etwa 20 Sekunden.','Introduce a current dish aloud, naming its main ingredient, preparation and one accompaniment. Use verified information and keep it to about 20 seconds.','Présentez à voix haute un plat actuel avec son produit principal, sa préparation et un accompagnement. Utilisez des informations vérifiées et visez une vingtaine de secondes.'),
 recovery:T('Formuliere eine ruhige erste Antwort auf die Beschwerde dieser Einheit. Kläre, welchen nächsten Schritt du selbst veranlassen darfst.','Prepare a calm first response to this lesson’s complaint. Find out which next step you are authorised to arrange.','Préparez une réponse calme à la réclamation de cette séquence. Vérifiez ensuite ce que vous pouvez proposer vous-même et ce qui nécessite l’accord du responsable.'),
 cheese:T('Lies die Angaben zu einem angebotenen Käse oder Dessert. Bereite eine kurze Beschreibung mit zwei bestätigten geschmacklichen Eigenschaften vor.','Read the information for an available cheese or dessert. Prepare a short description with two supported flavour characteristics.','Renseignez-vous sur un fromage ou un dessert de la carte. Préparez une courte description à partir de deux caractéristiques que vous avez vérifiées.'),
 tea:T('Prüfe für ein angebotenes Heißgetränk Preis, Menge und Hauszubereitung. Bereite eine kurze Auskunft für den Gast vor.','Check the price, serving size and house preparation for one hot drink. Prepare a brief explanation for a guest.','Vérifiez le prix, la quantité et la préparation maison d’une boisson chaude. Préparez une brève explication pour un convive.'),
 hygiene:T('Prüfe im Reinigungsplan deiner Station, wie saubere und benutzte Utensilien getrennt werden, und wende diese Trennung im nächsten Dienst an.','Check your station’s cleaning plan for separating clean and used utensils, and apply it on your next shift.','Vérifiez dans le plan de nettoyage de votre poste comment séparer les ustensiles propres et utilisés, puis appliquez cette séparation au prochain service.'),
 farewell:T('Prüfe eine fiktive Rechnung auf Zuordnung, Mengen und Summe. Formuliere danach eine höfliche Frage zur gemeinsamen oder getrennten Zahlung.','Check a fictional bill for table allocation, quantities and total. Then prepare a polite question about paying together or separately.','Sur une addition fictive, vérifiez la table, les quantités et le total. Préparez une question simple pour savoir si les clients souhaitent régler ensemble ou séparément.')
};
let practiceDone=read('practice-v3',null);
if(!practiceDone||typeof practiceDone!=='object'){
 practiceDone={};const old=read('taskChecks',{});
 // Only the table check is unchanged; other new tasks need a new confirmation.
 if((old.mise||[]).filter(Boolean).length===3)practiceDone.mise=true;
 write('practice-v3',practiceDone);
}
let lastLesson=read('lastLesson',null),labContext=null;
const labLessons=['cooking','pairing','zero'];
const digitalCount=()=>LESSONS.filter(l=>completed.includes(l.id)).length;
const practiceCount=()=>LESSONS.filter(l=>practiceDone[l.id]).length;
function nextLesson(){return LESSONS.find(l=>l.id===lastLesson&&!completed.includes(l.id))||LESSONS.find(l=>!completed.includes(l.id));}
function statuses(id){const state=completed.includes(id)?T('Abgeschlossen','Completed','Terminée'):(selectedAnswers[id]!==undefined||lastLesson===id||read('lesson-stages',{})[id])?T('Begonnen','Started','Commencée'):T('Noch nicht begonnen','Not started','Pas encore commencée');return `<span class="flow-status">${txt(state)}</span>`;}
canComplete=function(id){return selectedAnswers[id]===LESSONS.find(l=>l.id===id)?.answer;};
function completeDigital(id){
 if(!canComplete(id)&&!completed.includes(id))return;
 saveDraft();if(!completed.includes(id)){completed.push(id);write('completed',completed);}
 const index=LESSONS.findIndex(l=>l.id===id);lastLesson=LESSONS.slice(index+1).find(l=>!completed.includes(l.id))?.id||LESSONS.find(l=>!completed.includes(l.id))?.id||null;write('lastLesson',lastLesson);
 location.hash='journey';
}
const priorHome=home;
home=function(){
 let html=priorHome(),next=nextLesson(),started=!!lastLesson||digitalCount()>0;
 const title=T('Dein erster Service.','Your first service.','Vos premiers pas en salle.');
 html=html.replace(`<h1>${txt(UI.home)}</h1>`,`<h1>${txt(title)}</h1>`);
 html=html.replace(/<a class="primary" href="#beginning">.*?<\/a>/,`<p class="entry-facts">${txt(T('Etwa 5–10 Minuten pro Einheit. Du brauchst nur dein Smartphone oder deinen Computer.','About 5–10 minutes per lesson. All you need is your phone or computer.','Environ 5 à 10 minutes par séquence. Un téléphone ou un ordinateur suffit.'))}</p><a class="primary" href="#${started?'journey':'lesson/welcome'}">${txt(started?T('Meinen Lernweg fortsetzen','Continue my learning journey','Reprendre mon parcours'):FLOW.start)}${arrow}</a><a class="entry-secondary" href="#beginning">${txt(T('So funktioniert der Lernweg','How the learning journey works','Comment se déroule le parcours'))}</a>`);
 html=html.replace(/<li><span>03<\/span>.*?<\/li>/,`<li><span>03</span><h3>${txt(T('Im Dienst anwenden','Apply it on your shift','Appliquer en service'))}</h3><p>${txt(T('Am Ende jeder Einheit bekommst du eine kleine Aufgabe für deinen nächsten Dienst. Nimm sie mit und probiere das Gelernte aus.','Each lesson ends with a small task for your next shift. Take it with you and put what you learned into practice.','Chaque séquence se termine par un petit exercice pour votre prochain service. Gardez-le en tête et mettez vos acquis en pratique.'))}</p></li>`);
 html=html.replace(/<div class="invitation-art">.*?<\/div>/,'');
 html=html.replace(txt(T('Mit dem Empfang beginnen','Begin with the welcome','Commencer par l’accueil')),txt(FLOW.start));
 return html;
};
journey=function(){
 const next=nextLesson(),started=!!lastLesson||digitalCount()>0;
 return `<section class="section flow-dashboard"><div class="section-head"><h1>${txt(started?FLOW.resume:T('Dein erster Service','Your first service','Vos premiers pas en salle'))}</h1><p>${txt(T('Mach dort weiter, wo du aufgehört hast.','Continue where you left off.','Reprenez là où vous en étiez.'))}</p></div><section class="continue-panel"><div><h2>${next?txt(next.title):txt(T('Alle Einheiten sind abgeschlossen.','You have completed every lesson.','Vous avez terminé toutes les séquences.'))}</h2><p>${next?txt(next.lead):txt(T('Die Einheiten und ihre Aufgaben bleiben zum Nachschlagen da. Besprich mit deinem Serviceleiter, was du schon selbstständig übernehmen kannst.','The lessons and their tasks are still here to revisit. Discuss with your service manager what you can now do independently.','Vous pouvez toujours revenir aux séquences et à leurs exercices. Voyez avec votre responsable ce que vous pouvez désormais faire seul.'))}</p>${next?`<p class="hint">${txt(T('Etwa 5–10 Minuten','About 5–10 minutes','Environ 5 à 10 minutes'))}</p><a class="primary" href="#lesson/${next.id}">${txt(started?T('Diese Einheit fortsetzen','Continue with this lesson','Poursuivre cette séquence'):FLOW.start)}${arrow}</a>`:''}</div></section><div class="flow-progress"><p><strong>${digitalCount()} / ${LESSONS.length}</strong> ${txt(T('Einheiten abgeschlossen','lessons completed','séquences terminées'))}</p></div><h2 class="all-lessons-title">${txt(T('Alle Einheiten','All lessons','Toutes les séquences'))}</h2>${UI.chapters.map((c,g)=>`<section class="chapter"><div class="chapter-title"><small>${g+1} / 5</small><h3>${txt(c)}</h3></div><div>${LESSONS.filter(l=>l.group===g).map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="row-number">${LESSONS.indexOf(l)+1}</span><span class="row-title">${txt(l.title)}${statuses(l.id)}</span><span class="row-meta">5–10 min ${arrow}</span></a>`).join('')}</div></section>`).join('')}<p class="hint">${txt(UI.privacy)}</p></section>`;
};
function embeddedLab(id){
 if(['senses','describe'].includes(id))return `<section class="flow-lab" id="lesson-lab"><h2>${txt(T('Im Labor: die passenden Wörter finden','In the lab: finding the right words','Au laboratoire : trouver les mots justes'))}</h2><p>${txt(T('Wähle eine Aromengruppe und lies die Beispiele. Welches Wort würdest du einem Gast gegenüber verwenden?','Choose an aroma group and read the examples. Which word would you use with a guest?','Choisissez une famille aromatique et lisez les exemples. Quel mot utiliseriez-vous avec un convive ?'))}</p><div class="aroma-buttons">${AROMAS.map((a,i)=>`<button data-aroma="${i}" aria-pressed="${i===aromaIndex}">${txt(a[0])}</button>`).join('')}</div><p>${txt(AROMAS[aromaIndex][1])}</p><p>${txt(AROMAS[aromaIndex][2])}</p></section>`;
 if(!labLessons.includes(id))return '';
 const fragment=labPage().match(/<section class="lab">[\s\S]*?<\/section>/)[0].replace(/<img[^>]*>/g,'').replace('<h2>','<h3>').replace('</h2>','</h3>');
 return `<section class="flow-lab" id="lesson-lab"><h2>${txt(T('Im Labor: eine Begleitung ausprobieren','In the lab: try a pairing','Au laboratoire : essayer un accord'))}</h2><p>${txt(T('Wähle zuerst Gericht und Zubereitung, dann eine Begleitung. Lass dir die Kombination erklären und vergleiche eine zweite. Achte darauf, was Sauce und Intensität verändern.','Choose a dish and preparation, then a drink. Read the explanation and compare a second pairing. Notice how sauce and intensity affect the result.','Choisissez le plat et sa préparation, puis une boisson. Lisez l’explication et comparez un second accord. Observez le rôle de la sauce et de l’intensité.'))}</p>${fragment}<p class="hint">${txt(T('Ein Lernbeispiel, kein Geschmackstest. Die tatsächlichen Produkte und der Wunsch des Gastes entscheiden. Das Labor ist eine Vertiefung, keine zusätzliche Abschlusshürde.','A learning example, not a tasting test. Actual products and guest preferences decide. The lab offers further exploration and is not required for completion.','Ces exemples vous aident à réfléchir aux accords. En pratique, goûtez les produits et tenez compte des préférences du client. Cet exercice est facultatif.'))}</p></section>`;
}
lessonPage=function(id){
 const l=LESSONS.find(l=>l.id===id);if(!l)return home();
 lastLesson=id;write('lastLesson',id);
 if(labContext!==id){labContext=id;pairDish=id==='zero'?2:0;pairVariant=id==='pairing'||id==='cooking'?1:0;pairMode=id==='zero'?'zero':'wine';pairDrink=0;pairRevealed=false;}
 const chosen=selectedAnswers[id],pass=canComplete(id),done=completed.includes(id);
 return `<div class="page-title"><a class="back" href="#journey">${txt(FLOW.overview)}</a><h1>${txt(l.title)}</h1><p>${txt(l.lead)}</p>${statuses(id)}</div><section class="flow-route" aria-label="${txt(T('Ablauf dieser Einheit','Lesson sequence','Déroulement de la séquence'))}"><span>${LESSONS.indexOf(l)+1} / ${LESSONS.length} · 5–10 min</span><p>${txt(T('Situation → Erklärung → Entscheidung → Rückmeldung. Danach: eine Praxisaufgabe für deinen Dienst.','Situation → explanation → decision → feedback. Then: one practice task for your shift.','Une situation, une courte explication, une question et un retour sur votre réponse. Puis un exercice à essayer pendant le service.'))}</p></section><section class="flow-situation"><h2>${txt(T('Stell dir vor …','Imagine this …','Imaginez la situation…'))}</h2><p>${txt(l.q)}</p><a href="#reading" data-flow-scroll="reading">${txt(T('Worauf kommt es an?','What should you consider?','Quels sont les points essentiels ?'))} ↓</a></section><article class="flow-reading" id="reading"><h2>${txt(UI.know)}</h2>${txt(l.body).split('||').map(p=>`<p>${p}</p>`).join('')}<details class="reading-sources"><summary>${txt(UI.source)}</summary>${l.sources.map(i=>`<a href="${SOURCES[i].url}" target="_blank" rel="noopener noreferrer">${SOURCES[i].name}</a>`).join('')}</details></article>${embeddedLab(id)}<section class="exercise" id="decision"><div class="exercise-inner"><h2>${txt(T('Wie entscheidest du dich?','What would you do?','Que choisissez-vous ?'))}</h2><p class="question">${txt(l.q)}</p><div class="options">${l.options.map((o,i)=>`<button class="option ${chosen===i?'selected':''}" data-answer="${i}" data-lesson="${id}" aria-pressed="${chosen===i}"><span>${String.fromCharCode(65+i)}</span><span>${txt(o)}</span></button>`).join('')}</div><div class="feedback" aria-live="polite">${chosen!==undefined?`<strong>${txt(pass?UI.correct:UI.retry)}</strong><p>${txt(l.feedbackByChoice?.[chosen]||l.feedback)}</p>`:''}</div><div class="digital-finish"><p>${txt(done?FLOW.digital:pass?FLOW.ready:FLOW.finishFirst)}</p><button class="primary" id="complete" data-lesson="${id}" ${pass||done?'':'disabled'}>${txt(done?T('Zurück zu meinem Lernweg','Back to my learning journey','Revenir à mon parcours'):FLOW.next)}${arrow}</button></div></div></section><section class="flow-practice" id="practice"><h2>${txt(FLOW.practice)}</h2><p>${txt(PRACTICE[id])}</p><label class="practice-check"><input type="checkbox" id="practice-confirm" data-lesson="${id}" ${practiceDone[id]?'checked':''}>${txt(T('Ich habe diese Aufgabe ausprobiert oder geklärt.','I have tried or checked this task.','J’ai réalisé cet exercice ou vérifié les informations.'))}</label><p class="hint">${txt(FLOW.practiceHint)}</p><p id="practice-status" role="status">${txt(practiceDone[id]?FLOW.practised:FLOW.pending)}</p></section><section class="lesson-end flow-notes"><details><summary>${txt(T('Eine persönliche Notiz festhalten · freiwillig','Keep a personal note · optional','Garder une note personnelle · facultatif'))}</summary><label for="reflection">${txt(UI.reflect)}</label><textarea id="reflection" data-draft="${id}" rows="3">${esc(read('draft-'+id,''))}</textarea><button class="text-button" id="save-reflection" data-lesson="${id}">${txt(UI.save)}</button><p id="note-status" role="status"></p></details><a href="#journey">${txt(FLOW.overview)} ${arrow}</a></section>`;
};
bind=function(){
 baseBind();
 document.querySelectorAll('[data-flow-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.flowScroll)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
 $('#practice-confirm')?.addEventListener('change',e=>{const id=e.target.dataset.lesson;practiceDone[id]=e.target.checked;write('practice-v3',practiceDone);$('#practice-status').textContent=txt(practiceDone[id]?FLOW.practised:FLOW.pending);const badge=document.querySelector('.page-title .flow-status');if(badge)badge.outerHTML=statuses(id);});
};

// Show only the current step; sources, lab and workplace practice remain available on demand.
let lessonStages=read('lesson-stages',{});
const expandedLesson=lessonPage;
lessonPage=function(id){
 const l=LESSONS.find(l=>l.id===id);if(!l)return home();
 const full=expandedLesson(id),stage=location.hash.endsWith('/practice')?'done':lessonStages[id]||(completed.includes(id)?'done':'read');
 const n=LESSONS.indexOf(l),next=LESSONS.slice(n+1).find(x=>!completed.includes(x.id))||LESSONS.find(x=>!completed.includes(x.id));
 const heading=`<div class="page-title compact-title"><a class="back" href="#journey">${txt(FLOW.overview)}</a><p class="lesson-position">${txt(T('Einheit','Lesson','Séquence'))} ${n+1} / ${LESSONS.length} · 5–10 min</p><h1>${txt(l.title)}</h1>${art(l.art,'lesson-signature')}</div>`;
 const tabs=`<nav class="lesson-steps" aria-label="${txt(T('Lernschritte','Lesson steps','Étapes'))}"><button data-stage="read" data-id="${id}" aria-current="${stage==='read'?'step':'false'}">1. ${txt(T('Lesen','Read','Lire'))}</button><button data-stage="question" data-id="${id}" aria-current="${stage==='question'?'step':'false'}">2. ${txt(T('Entscheiden','Decide','Choisir'))}</button></nav>`;
 if(stage==='read'){
  const reading=full.match(/<article class="flow-reading"[\s\S]*?<\/article>/)[0];
  const lab=embeddedLab(id);
  return heading+tabs+`<div class="compact-learning"><p class="compact-situation">${txt(l.q)}</p>${reading}<div class="step-action"><button class="primary" data-stage="question" data-id="${id}">${txt(T('Zur Frage','Go to the question','Passer à la question'))}${arrow}</button></div>${lab?`<details class="optional-lab"><summary>${txt(T('Im Geschmackslabor ausprobieren · freiwillig','Explore in the tasting lab · optional','Essayer au laboratoire du goût · facultatif'))}</summary>${lab}</details>`:''}</div>`;
 }
 if(stage==='question'){
  let exercise=full.match(/<section class="exercise"[\s\S]*?<\/section>/)[0];
  exercise=exercise.replace(/<div class="digital-finish">[\s\S]*?<\/div>/,`<div class="digital-finish">${canComplete(id)?`<button class="primary" id="complete" data-lesson="${id}">${txt(T('Einheit abschließen','Complete lesson','Terminer la séquence'))}${arrow}</button>`:`<p class="hint">${txt(T('Wähle die Antwort, die am besten zur Situation passt.','Choose the answer that best fits the situation.','Choisissez la réponse la mieux adaptée à la situation.'))}</p>`}</div>`);
  return heading+tabs+exercise;
 }
 const notes=full.match(/<section class="lesson-end flow-notes">[\s\S]*?<\/section>/)[0];
 return heading+`<section class="lesson-success"><h2>${txt(T('Einheit abgeschlossen.','Lesson complete.','Séquence terminée.'))}</h2><div class="take-to-service"><h3>${txt(T('Deine Aufgabe für den nächsten Dienst','Your task for the next shift','Votre exercice pour le prochain service'))}</h3><p>${txt(PRACTICE[id])}</p></div>${next?`<a class="primary next-unit" href="#lesson/${next.id}">${txt(T('Nächste Einheit:','Next lesson:','Séquence suivante :'))} ${txt(next.title)}${arrow}</a>`:`<a class="primary" href="#journey">${txt(FLOW.overview)}${arrow}</a>`}<button class="text-button" data-stage="read" data-id="${id}">${txt(T('Noch einmal ansehen','Review this lesson','Revoir cette séquence'))}</button></section>${notes}`;

};
completeDigital=function(id){
 if(!canComplete(id))return;
 saveDraft();if(!completed.includes(id)){completed.push(id);write('completed',completed);}
 lessonStages[id]='done';write('lesson-stages',lessonStages);render();
};
const stepBind=bind;
bind=function(){
 stepBind();
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{saveDraft();lessonStages[b.dataset.id]=b.dataset.stage;write('lesson-stages',lessonStages);if(location.hash.endsWith('/practice'))location.hash='lesson/'+b.dataset.id;else render();});
 // Keep the optional lab open while its controls redraw the page.
 const lab=document.querySelector('.optional-lab');
 if(lab){const key='lab-open-'+lastLesson;lab.open=!!read(key,false);lab.querySelector('summary').addEventListener('click',e=>{e.preventDefault();lab.open=!lab.open;write(key,lab.open);});}
};
