const notebookPageWithExamples=notesPage;
notesPage=function(){
 let html=notebookPageWithExamples();
 const examples=`<div class="notebook-examples"><h2>${txt(T('Zum Beispiel','For example','Par exemple'))}</h2><ul>${notebookExamples.map(e=>`<li>${txt(e)}</li>`).join('')}</ul><p class="hint">${txt(T('Notiere deine Beobachtungen, keine Namen oder persönlichen Angaben zu Gästen.','Record your observations, not guests’ names or personal details.','Notez vos observations, sans noms ni informations personnelles sur les convives.'))}</p></div>`;
 html=html.replace(`<p class="hint">${txt(UI.privacy)}</p>`,examples+`<p class="hint">${txt(UI.privacy)}</p>`);
 html=html.replace(/<img[^>]*>/g,'');
 return html;
};
